  private todos: any[] = [];

  async query(sql: string, params: any[] = []): Promise<any[]> {
    const sqlLower = sql.toLowerCase();

    if (sqlLower.includes('insert into todos')) {
      this.todos.push({
        id: params[0],
        title: params[1],
        description: params[2],
        completed: params[3],
        createdAt: params[4]
      });
      return [];
    }

    if (sqlLower.includes('select * from todos where id')) {
      return this.todos.filter(t => t.id === params[0]);
    }

    if (sqlLower.includes('select * from todos')) {
      return [...this.todos].sort((a, b) => 
        b.createdAt.getTime() - a.createdAt.getTime()
      );
    }

    if (sqlLower.includes('update todos set completed')) {
      const todo = this.todos.find(t => t.id === params[1]);
      if (todo) todo.completed = params[0];
      return [];
    }

    if (sqlLower.includes('delete from todos')) {
      const index = this.todos.findIndex(t => t.id === params[0]);
      if (index !== -1) this.todos.splice(index, 1);
      return [];
    }

    return [];
  }
}

